import 'dart:io';
import 'package:webcommander_sdk/webcommander_sdk.dart';

final env = Platform.environment;
ClientRegistry.registerInstances([
  SdkConfig(
    AuthConfig(
      clientName: 'default',
      baseUrl: env['WC_BASE_URL']!,
      clientId: env['WC_CLIENT_ID']!,
      clientSecret: env['WC_CLIENT_SECRET']!,
      redirectUri: env['WC_REDIRECT_URI']!,
      authString: env['WC_AUTH_STRING']!,
    ),
    raiseOnError: true,
  ),
]);
